package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

/**
 * Reproduces the reported "slow, slow, fast, slow, and never fast again" sequence: a physical strategy that
 * demonstrably runs faster than the incumbent is executed once and then never chosen again.
 * <p>
 * Two independent defects produce it. First, a bounded probe that stops because it filled its private row buffer is
 * recorded as if it had run out of <em>time</em> — a right-censored latency at the full deadline plus a scheduler
 * strike — even though filling a buffer says something about how many rows the answer has, not about how slow the
 * strategy is. Second, a must-try strategy gets exactly one mandatory trial ever, and a single measurement cannot clear
 * the 99% displacement test unless the measured gap is roughly elevenfold, so a strategy that is merely three times
 * faster is locked out forever.
 */
class LmdbNativeFastRunLatchTest {

	/** Incumbent price used throughout: 5 ms, comfortably above the probe deadline floor. */
	private static final double INCUMBENT_NANOS = 5_000_000.0;
	/** Rival price: 3.3x faster than the incumbent — a real win, but far below the single-sample displacement bar. */
	private static final double RIVAL_NANOS = 1_500_000.0;

	private record Fixture(LmdbNativeStoreCostModel store, LmdbNativeAdaptiveCostModel model) {
	}

	/**
	 * An empty store wrapped in a recording model. Both fixtures below keep the shared machine model under its
	 * {@code MINIMUM_ADAPTIVE_SAMPLES} of 32, so every arm stays in the DIRECT lane and the posterior models log
	 * runtime itself — which is what makes the displacement arithmetic in these tests reproducible.
	 */
	private static Fixture emptyFixture() {
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
		LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(), store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
		store.safetyLedger().earn(1_000_000_000_000L);
		return new Fixture(store, model);
	}

	/**
	 * A store trained through the estimates the arbiter itself derives from a proposal. Training a hand-built estimate
	 * instead would settle a different variant key than the one dispatch prices, leaving the incumbent unpriceable and
	 * suppressing probing entirely.
	 */
	private static Fixture arbiterFixture() {
		Fixture fixture = emptyFixture();
		LmdbNativeCostEstimate incumbent = proposal("incumbent", LmdbNativeAttemptMetrics.PATH_BATCH,
				new AtomicInteger()).adaptiveEstimate(-1D);
		for (int i = 0; i < 20; i++) {
			fixture.model()
					.recordCompleted(incumbent, incumbent.total(), INCUMBENT_NANOS, 1.0,
							fixture.model().currentRegime());
		}
		return fixture;
	}

	/** A store trained through the hand-built estimates the policy-level tests hand to {@code choose}. */
	private static Fixture policyFixture() {
		Fixture fixture = emptyFixture();
		LmdbNativeCostEstimate incumbent = estimate(LmdbNativeAttemptMetrics.PATH_BATCH);
		for (int i = 0; i < 20; i++) {
			fixture.model()
					.recordCompleted(incumbent, incumbent.total(), INCUMBENT_NANOS, 1.0,
							fixture.model().currentRegime());
		}
		return fixture;
	}

	private static LmdbNativeCostEstimate estimate(String family) {
		LmdbNativePhysicalVariantKey key = LmdbNativePhysicalVariantKey.builder(family)
				.physicalOrderAndProperties(family)
				.build();
		LmdbNativeCostVector vector = LmdbNativeCostVector.point(LmdbNativeCostVector.Feature.SCANNED_ROW, 1_000);
		return new LmdbNativeCostEstimate(key, LmdbNativeCostVector.zero(), vector, 1_000, 0.1);
	}

	private static LmdbNativeStrategyProposal<String> proposal(String value, String tag, AtomicInteger opens) {
		return new LmdbNativeStrategyProposal<>(() -> {
			opens.incrementAndGet();
			return value;
		}, LmdbNativeWork.exact(1_000D), tag, () -> {
		});
	}

	/**
	 * A rival whose work is unknown, exactly like the parallel-pipeline proposals real dispatch sites offer: it quotes
	 * ORDINAL_ONLY until timed once, which is what makes it a probe-worthy unknown rather than a priced loser.
	 */
	private static LmdbNativeStrategyProposal<String> unpricedRival(String value, String tag, AtomicInteger opens) {
		return new LmdbNativeStrategyProposal<>(() -> {
			opens.incrementAndGet();
			return value;
		}, LmdbNativeWork.UNKNOWN, tag, () -> {
		});
	}

	/**
	 * Mimics {@code NativeProbeBufferHarness.drainBounded} at the moment it runs out of private buffer room, reporting
	 * it through the same single call the production harness uses.
	 */
	private static LmdbNativeProbeHarness<String> overflowingHarness() {
		return new LmdbNativeProbeHarness<>() {

			@Override
			public String drainBounded(String value, LmdbNativeCostObservation observation, int rowCap) {
				throw LmdbNativeProbeDeadline.capacityExhausted();
			}

			@Override
			public void discard(String value) {
				// nothing native is held by a String trial value
			}
		};
	}

	/**
	 * The reporting call every drain loop shares. Routing both the marking and the throw through one method is what
	 * makes the distinction between "out of time" and "out of buffer" impossible for a harness to get half-right, so
	 * this pins its two obligations directly.
	 */
	@Test
	void capacityExhaustedMarksTheDeadlineAsCapacityRatherThanTimeout() {
		try (LmdbNativeProbeDeadline.Scope scope = LmdbNativeProbeDeadline
				.enter(System.nanoTime() + Long.MAX_VALUE / 4)) {
			RuntimeException thrown = LmdbNativeProbeDeadline.capacityExhausted();

			assertSame(LmdbNativeProbeDeadlineExceeded.INSTANCE, thrown,
					"capacity unwinds through the same exception as a timeout so the abort path stays single");
			assertTrue(scope.deadline().capacityTripped(),
					"the cause must survive the unwind; without it the arbiter charges a timeout that never happened");
			assertTrue(scope.deadline().tripped(),
					"capacity still cancels the trial, so cooperative pollers must see the deadline tripped");
		}
	}

	/**
	 * A probe that fills its row buffer must not be recorded as a timeout. The trial here returns immediately — it is
	 * fast — and only the buffer runs out, so asserting that the true runtime exceeds the whole probe deadline is a
	 * fabrication. Today the arbiter records exactly that fabrication, because the harness reports buffer exhaustion
	 * through the same tripped deadline and the same exception as a real timeout.
	 */
	@Test
	void capacityExhaustionIsNeitherATimingCensorNorAStrike() throws IOException {
		Fixture fixture = arbiterFixture();
		LmdbNativeCostEstimate rivalEstimate;
		String result;
		AtomicInteger rivalOpens = new AtomicInteger();
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter
				.<String>forModel(null, -1D, fixture.model())
				.probeHarness(overflowingHarness())) {
			LmdbNativeStrategyProposal<String> rival = unpricedRival("rival",
					LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, rivalOpens);
			rivalEstimate = rival.directTimingEstimate();
			arbiter.offer(() -> proposal("incumbent", LmdbNativeAttemptMetrics.PATH_BATCH, new AtomicInteger()));
			arbiter.offer(() -> rival);
			result = arbiter.select();
		}

		assertEquals("incumbent", result, "the overflowing trial is abandoned and the incumbent answers the query");
		assertEquals(1, rivalOpens.get(), "the rival was probed exactly once");

		LmdbNativeRegimeKey regime = fixture.model().currentRegime();
		LmdbNativeCostPosteriorStore.ExactKey key = LmdbNativeCostPosteriorStore.ExactKey.of(regime,
				LmdbNativeCostPosteriorStore.Lane.DIRECT, rivalEstimate.variantKey());
		LmdbNativeCostPosteriorStore.Reading reading = fixture.store()
				.posteriors()
				.read(key, 0L, fixture.store().nowMillis());

		assertEquals(0, reading.exact().censoredCount,
				"running out of buffer room is not evidence that the strategy is slow, so no timing censor may be "
						+ "recorded against the full-run bucket");
		assertNotEquals(LmdbNativeProbeScheduler.State.DORMANT_UNTIL_EPOCH,
				fixture.store().probeScheduler().state(rivalEstimate.variantKey(), regime, 0L),
				"a capacity overflow may rest an arm but must never park it until the regime epoch changes");
	}

	/**
	 * A strategy measured faster than the incumbent, but by less than the roughly elevenfold gap a single measurement
	 * needs to clear the 99% displacement test, must keep earning trials until its posterior settles. Probing is
	 * disabled here so the only remaining exploration path is the mandatory must-try run, which today is gated on the
	 * arm having <em>never</em> executed and is therefore already closed after one measurement.
	 */
	@Test
	void aMeasuredFasterArmKeepsBeingExploredUntilItSettles() {
		Fixture fixture = policyFixture();
		LmdbNativeAdaptiveArbitration.Candidate<String> incumbent = candidate(LmdbNativeAttemptMetrics.PATH_BATCH, 0);
		LmdbNativeAdaptiveArbitration.Candidate<String> rival = candidate(LmdbNativeAttemptMetrics.PATH_IR_KERNEL, 1);
		fixture.model()
				.recordCompleted(rival.estimate(), rival.estimate().total(), RIVAL_NANOS, 1.0,
						fixture.model().currentRegime());

		LmdbNativeAdaptiveArbitration.DispatchPlan<String> plan = LmdbNativeAdaptiveArbitration.choose(
				List.of(incumbent, rival), fixture.model(),
				LmdbNativeAdaptiveArbitration.ProbeContext.disabled());

		assertSame(rival, selected(plan),
				"the rival measured " + (INCUMBENT_NANOS / RIVAL_NANOS) + "x faster on its only run; one measurement "
						+ "cannot clear the 99% displacement bar, so it must keep being explored rather than be "
						+ "locked out after a single trial");
	}

	/**
	 * The reported four-run sequence, replayed deterministically: elapsed times are supplied as arguments rather than
	 * measured, so the assertion does not depend on machine speed. After the rival's first fast measurement, every
	 * later dispatch must keep choosing it.
	 */
	@Test
	void aFastFirstMeasurementKeepsWinningAcrossFollowUpDispatches() {
		Fixture fixture = policyFixture();
		LmdbNativeAdaptiveArbitration.Candidate<String> incumbent = candidate(LmdbNativeAttemptMetrics.PATH_BATCH, 0);
		LmdbNativeAdaptiveArbitration.Candidate<String> rival = candidate(LmdbNativeAttemptMetrics.PATH_IR_KERNEL, 1);

		int rivalDispatches = 0;
		for (int dispatch = 1; dispatch <= 4; dispatch++) {
			LmdbNativeAdaptiveArbitration.DispatchPlan<String> plan = LmdbNativeAdaptiveArbitration.choose(
					List.of(incumbent, rival), fixture.model(),
					LmdbNativeAdaptiveArbitration.ProbeContext.disabled());
			LmdbNativeAdaptiveArbitration.Candidate<String> chosen = selected(plan);
			LmdbNativeCostEstimate ran = chosen.estimate();
			double elapsed = chosen == rival ? RIVAL_NANOS : INCUMBENT_NANOS;
			if (chosen == rival) {
				rivalDispatches++;
			}
			fixture.model().recordCompleted(ran, ran.total(), elapsed, 1.0, fixture.model().currentRegime());
		}

		assertEquals(4, rivalDispatches,
				"once the rival has measured faster than the incumbent it must keep being chosen; a single fast run "
						+ "followed by a permanent return to the slower strategy is the reported regression");
	}

	private static LmdbNativeAdaptiveArbitration.Candidate<String> candidate(String family, int preference) {
		return new LmdbNativeAdaptiveArbitration.Candidate<>(estimate(family), preference, observation -> family);
	}

	/** The candidate a plan will actually run, across all four plan shapes. */
	private static LmdbNativeAdaptiveArbitration.Candidate<String> selected(
			LmdbNativeAdaptiveArbitration.DispatchPlan<String> plan) {
		if (plan instanceof LmdbNativeAdaptiveArbitration.DispatchPlan.Normal<String> normal) {
			return normal.candidate();
		}
		if (plan instanceof LmdbNativeAdaptiveArbitration.DispatchPlan.Guarded<String> guarded) {
			return guarded.normal().candidate();
		}
		if (plan instanceof LmdbNativeAdaptiveArbitration.DispatchPlan.Probe<String> probe) {
			return probe.trial();
		}
		return ((LmdbNativeAdaptiveArbitration.DispatchPlan.Hedge<String>) plan).probe().trial();
	}
}
